fn append_array(mut a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Pre-allocate enough space to hold both vectors
    a.reserve(b.len());
    // Move all elements of b to the end of a
    a.extend(b);
    a
}

